func TestConcurrentFanout(t *testing.T) {
	const (
		cursorCount = 3
		itemCount   = 600
	)
	b := fanoutbuffer.NewBuffer[int](fanoutbuffer.Config{Capacity: 11})
	t.Cleanup(b.Close)
	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()
	type result struct {
		values []int
		err    error
	}
	results := make(chan result, cursorCount)
	for i := 0; i < cursorCount; i++ {
		c := b.NewCursor()
		go func() {
			defer c.Close()
			values := make([]int, 0, itemCount)
			for len(values) < itemCount {
				var out [17]int
				n, err := c.Read(ctx, out[:])
				if err != nil {
					results <- result{err: err}
					return
				}
				if n == 0 {
					results <- result{err: fmt.Errorf("Read returned no items without an error")}
					return
				}
				values = append(values, out[:n]...)
			}
			results <- result{values: values}
		}()
	}

	for start := 0; start < itemCount; start += 23 {
		end := min(start+23, itemCount)
		batch := make([]int, 0, end-start)
		for value := start; value < end; value++ {
			batch = append(batch, value)
		}
		b.Append(batch...)
	}
	for i := 0; i < cursorCount; i++ {
		var got result
		select {
		case got = <-results:
		case <-ctx.Done():
			t.Fatal("timed out waiting for concurrent readers")
		}
		require.NoError(t, got.err)
		require.Len(t, got.values, itemCount)
		for value, actual := range got.values {
			require.Equal(t, value, actual)
		}
	}
}

